# region: shape
def shape(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: digest
def digest(xs, floor_=6):
    return [v for v in xs if v >= floor_]

# region: gather
def gather(xs, floor_=6):
    return [v for v in xs if v >= floor_]

# region: intake
def intake(xs, offset=-1):
    return [v - offset for v in xs]

# region: fold
def fold(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: emit
def emit(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return emit(fold(intake(gather(digest(shape(raw))))))

